SELECT store_sales.product_id, CASE WHEN YEAR(store_sales.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(store_sales.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MAX(inventory.quantity) AS max_quantity FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id GROUP BY store_sales.product_id, CASE WHEN YEAR(store_sales.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(store_sales.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END;
